// Transcripts search ran first; summaries search ran second.
// Both results are accessible by node name.
const transcriptFiles = $('Search Transcripts Intake Folders').first().json.files || [];
const summaryFiles = $('Search Summaries Intake Folders').first().json.files || [];

// Parse company name out of "Transcripts (Company Name Intake)"
const parseTranscripts = name => {
  const m = name.match(/^Transcripts \((.+) Intake\)$/);
  return m ? m[1] : null;
};

// Parse company name out of "Summaries (Company Name Intake)"
const parseSummaries = name => {
  const m = name.match(/^Summaries \((.+) Intake\)$/);
  return m ? m[1] : null;
};

// Build a lookup: companyName → summaries folder ID
const summariesMap = {};
for (const f of summaryFiles) {
  const company = parseSummaries(f.name);
  if (company) summariesMap[company] = f.id;
}

// Join on company name
const clients = [];
for (const f of transcriptFiles) {
  const company = parseTranscripts(f.name);
  if (!company || !summariesMap[company]) continue;
  clients.push({
    name: company,
    transcripts_folder_id: f.id,
    summaries_folder_id: summariesMap[company]
  });
}

clients.sort((a, b) => a.name.localeCompare(b.name));

return [{ json: { clients } }];

const body = $input.first().json.body || {};

if (!body.transcript_text || typeof body.transcript_text !== 'string' || !body.transcript_text.trim()) {
  throw new Error('Missing required field: transcript_text');
}

const MAX_CHARS = 120000;
const transcript = body.transcript_text.length > MAX_CHARS
  ? body.transcript_text.slice(0, MAX_CHARS)
  : body.transcript_text;

return [{ json: { transcript } }];

