const summary = $json?.choices?.[0]?.message?.content || '';
if (!summary) throw new Error('Grok returned an empty summary');
return [{ json: { ok: true, summary } }];

const body = $input.first().json.body || {};

const required = ['filename', 'transcript', 'summary', 'transcripts_folder_id', 'summaries_folder_id'];
for (const field of required) {
  if (!body[field] || (typeof body[field] === 'string' && !body[field].trim())) {
    throw new Error(`Missing required field: ${field}`);
  }
}

// Strip extension from filename if present — we add _transcript.txt / _summary.txt ourselves
const baseName = body.filename.replace(/\.[^.]+$/, '');

return [{
  json: {
    filename: baseName,
    transcript: body.transcript,
    summary: body.summary,
    transcripts_folder_id: body.transcripts_folder_id,
    summaries_folder_id: body.summaries_folder_id
  }
}];

// Stash the transcript upload result and carry the validated fields forward
// so the summary upload node has everything it needs.
const upload = $input.first().json;
const validated = $('Validate Ingest Input').first().json;

return [{
  json: {
    transcript_file_id: upload.id,
    transcript_url: upload.webViewLink || `https://drive.google.com/file/d/${upload.id}/view`,
    filename: validated.filename,
    summary: validated.summary,
    summaries_folder_id: validated.summaries_folder_id
  }
}];

const summaryUpload = $input.first().json;
const prep = $('Prep Summary Upload').first().json;

return [{
  json: {
    ok: true,
    transcript_file_id: prep.transcript_file_id,
    transcript_url: prep.transcript_url,
    summary_file_id: summaryUpload.id,
    summary_url: summaryUpload.webViewLink || `https://drive.google.com/file/d/${summaryUpload.id}/view`
  }
}];
